66	static struct svm_cpy_host_pool_bucket *svm_cpy_host_pool_get_bucket(u64 size, u32 *bucket_idx)
67	{
68	    u32 i;
69	
70	    for (i = 0; i < SVM_CPY_HOST_POOL_BUCKET_NUM; i++) {
71	        if (size <= g_svm_cpy_host_pool[i].chunk_size) {
72	            *bucket_idx = i;
73	            return &g_svm_cpy_host_pool[i];
74	        }
75	    }
76	
77	    return NULL;
78	}
