80	static void svm_cpy_host_pool_bucket_reset(struct svm_cpy_host_pool_bucket *bucket)
81	{
82	    bitmap_clear(bucket->bitmap, 0, (int)bucket->chunk_num);
83	    bucket->free_num = bucket->chunk_num;
84	}
