86	static int svm_cpy_host_pool_bucket_init(struct svm_cpy_host_pool_bucket *bucket)
87	{
88	    void *host_va = NULL;
89	    int ret;
90	
91	    if (bucket->base_va != 0) {
92	        return DRV_ERROR_NONE;
93	    }
94	
95	    ret = svm_mem_malloc(&host_va, bucket->chunk_size * bucket->chunk_num,
96	                         MEM_HOST | ((u64)DEVMM_MODULE_ID << MEM_MODULE_ID_BIT));
97	    if (ret != DRV_ERROR_NONE) {
98	        return ret;
99	    }
100	
101	    bucket->base_va = (u64)(uintptr_t)host_va;
102	    svm_cpy_host_pool_bucket_reset(bucket);
103	    return DRV_ERROR_NONE;
104	}
105	
106	static void svm_cpy_host_pool_bucket_uninit(struct svm_cpy_host_pool_bucket *bucket)
107	{
108	    if (bucket->base_va != 0) {
109	        (void)svm_mem_free((void *)(uintptr_t)bucket->base_va);
110	        bucket->base_va = 0;
111	    }
112	
113	    svm_cpy_host_pool_bucket_reset(bucket);
114	}
