116	static int svm_cpy_host_pool_init(void)
117	{
118	    u32 ready_bucket_num = 0;
119	    u32 i;
120	
121	    if (g_svm_cpy_host_pool_state == SVM_CPY_HOST_POOL_READY) {
122	        return DRV_ERROR_NONE;
123	    }
124	
125	    if (g_svm_cpy_host_pool_state == SVM_CPY_HOST_POOL_FAIL) {
126	        return DRV_ERROR_NOT_SUPPORT;
127	    }
128	
129	    for (i = 0; i < SVM_CPY_HOST_POOL_BUCKET_NUM; i++) {
130	        int ret = svm_cpy_host_pool_bucket_init(&g_svm_cpy_host_pool[i]);
131	
132	        if (ret != DRV_ERROR_NONE) {
133	            svm_warn("Alloc memcpy host svm pool failed. (ret=%d; chunk_size=%llu; chunk_num=%u)\n", ret,
134	                     g_svm_cpy_host_pool[i].chunk_size, g_svm_cpy_host_pool[i].chunk_num);
135	            continue;
136	        }
137	
138	        ready_bucket_num++;
139	    }
140	
141	    if (ready_bucket_num == 0) {
142	        g_svm_cpy_host_pool_state = SVM_CPY_HOST_POOL_FAIL;
143	        return DRV_ERROR_NOT_SUPPORT;
144	    }
145	
146	    g_svm_cpy_host_pool_state = SVM_CPY_HOST_POOL_READY;
147	    return DRV_ERROR_NONE;
148	}
