150	void svm_cpy_host_pool_uninit(void)
151	{
152	    u32 i;
153	
154	    for (i = 0; i < SVM_CPY_HOST_POOL_BUCKET_NUM; i++) {
155	        svm_cpy_host_pool_bucket_uninit(&g_svm_cpy_host_pool[i]);
156	    }
157	
158	    g_svm_cpy_host_pool_state = SVM_CPY_HOST_POOL_UNINIT;
159	}
