161	static int _svm_cpy_host_pool_slot_get(struct svm_cpy_host_pool_bucket *bucket, u32 bucket_idx,
162	                                       struct svm_cpy_host_pool_slot *slot)
163	{
164	    u32 slot_idx;
165	
166	    if ((bucket->base_va == 0) || (bucket->free_num == 0)) {
167	        return DRV_ERROR_BUSY;
168	    }
169	
170	    slot_idx = (u32)bitmap_find_next_zero_area(bucket->bitmap, bucket->chunk_num, 0, 1, 0);
171	    if (slot_idx >= bucket->chunk_num) {
172	        return DRV_ERROR_BUSY;
173	    }
174	
175	    bitmap_set(bucket->bitmap, (int)slot_idx, 1);
176	    bucket->free_num--;
177	
178	    slot->bucket_idx = bucket_idx;
179	    slot->slot_idx = slot_idx;
180	    slot->va = bucket->base_va + (u64)slot_idx * bucket->chunk_size;
181	    return DRV_ERROR_NONE;
182	}
183	
184	static void _svm_cpy_host_pool_slot_put(struct svm_cpy_host_pool_slot *slot)
185	{
186	    struct svm_cpy_host_pool_bucket *bucket = &g_svm_cpy_host_pool[slot->bucket_idx];
187	
188	    bitmap_clear(bucket->bitmap, (int)slot->slot_idx, 1);
189	    bucket->free_num++;
190	
191	    slot->va = 0;
192	    slot->bucket_idx = 0;
193	    slot->slot_idx = 0;
194	}
