196	int svm_cpy_host_pool_slot_get(u64 size, struct svm_cpy_host_pool_slot *slot)
197	{
198	    struct svm_cpy_host_pool_bucket *bucket;
199	    u32 bucket_idx;
200	    int ret;
201	
202	    bucket = svm_cpy_host_pool_get_bucket(size, &bucket_idx);
203	    if (bucket == NULL) {
204	        return DRV_ERROR_NOT_SUPPORT;
205	    }
206	
207	    (void)pthread_mutex_lock(&g_svm_cpy_host_pool_mutex);
208	    if (g_svm_cpy_host_pool_state != SVM_CPY_HOST_POOL_READY) {
209	        (void)pthread_mutex_unlock(&g_svm_cpy_host_pool_mutex);
210	        return DRV_ERROR_NOT_SUPPORT;
211	    }
212	
213	    ret = _svm_cpy_host_pool_slot_get(bucket, bucket_idx, slot);
214	    (void)pthread_mutex_unlock(&g_svm_cpy_host_pool_mutex);
215	    return ret;
216	}
217	
218	void svm_cpy_host_pool_slot_put(struct svm_cpy_host_pool_slot *slot)
219	{
220	    (void)pthread_mutex_lock(&g_svm_cpy_host_pool_mutex);
221	    _svm_cpy_host_pool_slot_put(slot);
222	    (void)pthread_mutex_unlock(&g_svm_cpy_host_pool_mutex);
223	}
