234	    ret = svm_cpy_host_pool_init();
235	    (void)pthread_mutex_unlock(&g_svm_cpy_host_pool_mutex);
236	    if (ret != DRV_ERROR_NONE) {
237	        svm_warn("Init memcpy host pool failed. (ret=%d; devid=%u)\n", ret, devid);
238	    }
239	
240	    return DRV_ERROR_NONE;
241	}
242	
243	static int svm_cpy_host_pool_dev_uninit(u32 devid)
244	{
245	    if (devid != svm_get_host_devid()) {
246	        return DRV_ERROR_NONE;
247	    }
248	
249	    (void)pthread_mutex_lock(&g_svm_cpy_host_pool_mutex);
250	    svm_cpy_host_pool_uninit();
251	    (void)pthread_mutex_unlock(&g_svm_cpy_host_pool_mutex);
252	    return DRV_ERROR_NONE;
253	}
254	
255	static void __attribute__((constructor(SVM_INIT_PRI_FINAL))) svm_cpy_host_pool_module_init(void)
