260	    if (ret != DRV_ERROR_NONE) {
261	        svm_err("Register ioctl dev init post handle failed.\n");
262	    }
263	
264	    ret = svm_register_ioctl_dev_uninit_pre_handle(svm_cpy_host_pool_dev_uninit);
