45	static int svm_mem_sync_copy_h2d_by_pool(struct svm_copy_va_info *src_info, struct svm_copy_va_info *dst_info)
46	{
47	    struct svm_cpy_host_pool_slot slot = {0};
48	    struct svm_copy_va_info host_svm_info;
49	    int ret;
50	
51	    ret = svm_cpy_host_pool_slot_get(src_info->size, &slot);
52	    if (ret != DRV_ERROR_NONE) {
53	        return ret;
54	    }
55	
56	    ret = svm_memcpy_s((void *)(uintptr_t)slot.va, src_info->size, (void *)(uintptr_t)src_info->va, src_info->size);
57	    if (ret != 0) {
58	        svm_err("Memcpy by host svm pool failed. (dst=0x%llx; src=0x%llx; size=%llu; ret=%d)\n", slot.va, src_info->va,
59	                src_info->size, ret);
60	        ret = DRV_ERROR_INVALID_VALUE;
61	        goto out;
62	    }
63	
64	    svm_copy_va_info_pack(slot.va, src_info->size, svm_get_host_devid(), &host_svm_info);
65	    ret = svm_sync_copy(&host_svm_info, dst_info);
66	
67	out:
68	    svm_cpy_host_pool_slot_put(&slot);
69	    return ret;
70	}
