78	    ret = svm_cpy_host_pool_slot_get(dst_info->size, &slot);
79	    if (ret != DRV_ERROR_NONE) {
80	        return ret;
81	    }
82	
83	    svm_copy_va_info_pack(slot.va, dst_info->size, svm_get_host_devid(), &host_svm_info);
84	    ret = svm_sync_copy(src_info, &host_svm_info);
85	    if (ret != DRV_ERROR_NONE) {
86	        goto out;
87	    }
88	
89	    ret = svm_memcpy_s((void *)(uintptr_t)dst_info->va, dst_info->size, (void *)(uintptr_t)slot.va, dst_info->size);
90	    if (ret != 0) {
91	        svm_err("Memcpy by host svm pool failed. (dst=0x%llx; src=0x%llx; size=%llu; ret=%d)\n", dst_info->va, slot.va,
92	                dst_info->size, ret);
93	        ret = DRV_ERROR_INVALID_VALUE;
94	    }
95	
96	out:
97	    svm_cpy_host_pool_slot_put(&slot);
98	    return ret;
99	}
