101	static int svm_copy_check_addr_prop_consistency(struct svm_prop *tar_prop, u64 start, u64 end)
102	{
103	    struct svm_prop prop;
104	    u64 va;
105	    int ret;
106	
107	    for (va = start; va < end; va += prop.size) {
108	        ret = svm_get_prop(va, &prop);
109	        if (ret != DRV_ERROR_NONE) {
110	            svm_err("Invalid addr. (ret=%d; va=0x%llx)\n", ret, va);
111	            return DRV_ERROR_PARA_ERROR; /* Same to OBP. */
112	        }
113	
114	        if (((prop.flag & ~SVM_FLAG_ATTR_PA_P2P) != (tar_prop->flag & ~SVM_FLAG_ATTR_PA_P2P)) ||
115	            (prop.devid != tar_prop->devid)) {
116	            svm_err("Addr's prop is not consistent.\n");
117	            return DRV_ERROR_PARA_ERROR;
118	        }
119	    }
120	
121	    return DRV_ERROR_NONE;
122	}
