124	static int svm_copy_check_addr_prop_cap(u64 va, u64 size, u64 cap_mask)
125	{
126	    struct svm_prop prop;
127	    int va_type;
128	    int ret;
129	
130	    ret = svm_get_va_type(va, size, &va_type);
131	    if (ret != 0) {
132	        svm_err("Invalid addr. (va=0x%llx; size=0x%llx)\n", va, size);
133	        return ret;
134	    }
135	
136	    if (va_type == VA_TYPE_SVM) {
137	        ret = svm_get_prop(va, &prop);
138	        if (ret != DRV_ERROR_NONE) {
139	            /* The log cannot be modified, because in the failure mode library. */
140	            svm_err("Invalid addr. (ret=%d; va=0x%llx)\n", ret, va);
141	            return ret;
142	        }
143	
144	        if ((prop.flag & cap_mask) == 0) {
145	            svm_err("Va not support cur cap. (va=0x%llx; prop.flag=0x%llx)\n", va, prop.flag);
146	            return DRV_ERROR_PARA_ERROR;
147	        }
148	
149	        if ((va + size) > (prop.start + prop.size)) {
150	            ret = svm_copy_check_addr_prop_consistency(&prop, prop.start + prop.size, va + size);
151	            if (ret != DRV_ERROR_NONE) {
152	                return ret;
153	            }
154	        }
155	    }
156	
157	    return DRV_ERROR_NONE;
158	}
