197	static int svm_copy_real_info_pack(const struct svm_global_va *src_info, struct svm_copy_va_info *info)
198	{
199	    u32 host_tgid, proc_type;
200	    int ret;
201	
202	    if ((src_info->server_id != SVM_INVALID_SERVER_ID) && (src_info->server_id != svm_get_cur_server_id())) {
203	        svm_info("Cross server shared memcpy is not support. (server_id=%u; cur_server_id=%u)\n", src_info->server_id,
204	                 svm_get_cur_server_id());
205	        return DRV_ERROR_NOT_SUPPORT;
206	    }
207	
208	    ret = uda_get_devid_by_udevid_ex(src_info->udevid, &info->devid);
209	    if (ret != 0) {
210	        svm_err("Get devid by udevid failed. (ret=%d; udevid=%u)\n", ret, src_info->udevid);
211	        return ret;
212	    }
213	
214	    ret = halQueryMasterPidByDeviceSlave(info->devid, src_info->tgid, &host_tgid, &proc_type);
215	    if (ret != 0) {
216	        svm_err("Get master pid by device slave failed. (ret=%d; devid=%u; slave_pid=%d)\n", ret, info->devid,
217	                src_info->tgid);
218	        return ret;
219	    }
220	
221	    info->host_tgid = (int)host_tgid;
222	    info->va = src_info->va;
223	    info->size = src_info->size;
224	    info->is_share = true;
225	    return DRV_ERROR_NONE;
226	}
