228	static int svm_copy_try_query_shared_info(struct svm_copy_va_info *info, struct svm_copy_shared_info *shared)
229	{
230	    struct svm_global_va src_info;
231	    enum svm_copy_shared_type type;
232	    int ret;
233	
234	    shared->type = SVM_COPY_SHARED_NONE;
235	    shared->map_info = *info;
236	    shared->real_info = *info;
237	
238	    ret = svm_ipc_query_src_info(info->va, info->size, &src_info);
239	    if (ret == DRV_ERROR_NONE) {
240	        type = SVM_COPY_SHARED_IPC;
241	    } else {
242	        ret = vmm_query_ipc_src_info(info->va, info->size, &src_info);
243	        if (ret != DRV_ERROR_NONE) {
244	            return DRV_ERROR_NONE; /* Non shared addr, just return ok to continue copy. */
245	        }
246	        type = SVM_COPY_SHARED_VMM;
247	    }
248	
249	    ret = svm_copy_real_info_pack(&src_info, &shared->real_info);
250	    if (ret != DRV_ERROR_NONE) {
251	        return ret;
252	    }
253	    shared->type = type;
254	
255	    return DRV_ERROR_NONE;
256	}
