258	static int svm_copy_try_resolve_shared_info(struct svm_copy_va_info *src_info, struct svm_copy_va_info *dst_info,
259	                                            struct svm_copy_va_info *real_src, struct svm_copy_va_info *real_dst,
260	                                            bool *resolved)
261	{
262	    struct svm_copy_shared_info src_shared, dst_shared;
263	    bool src_is_shared, dst_is_shared;
264	    int ret;
265	
266	    ret = svm_copy_try_query_shared_info(src_info, &src_shared);
267	    if (ret != DRV_ERROR_NONE) {
268	        return ret;
269	    }
270	
271	    ret = svm_copy_try_query_shared_info(dst_info, &dst_shared);
272	    if (ret != DRV_ERROR_NONE) {
273	        return ret;
274	    }
275	
276	    src_is_shared = svm_copy_shared_info_is_valid(&src_shared);
277	    dst_is_shared = svm_copy_shared_info_is_valid(&dst_shared);
278	    if (!src_is_shared && !dst_is_shared) {
279	        *resolved = false;
280	        return DRV_ERROR_NONE;
281	    }
282	
283	    if (src_is_shared && dst_is_shared) {
284	        svm_info("Shared src and dst are not support. (src=0x%llx; dst=0x%llx)\n", src_info->va, dst_info->va);
285	        return DRV_ERROR_NOT_SUPPORT;
286	    }
287	
288	    *real_src = src_is_shared ? src_shared.real_info : *src_info;
289	    *real_dst = dst_is_shared ? dst_shared.real_info : *dst_info;
290	    real_src->is_share = src_is_shared;
291	    real_dst->is_share = dst_is_shared;
292	    *resolved = true;
293	    return DRV_ERROR_NONE;
294	}
