303	            "Resolved local copy tgid not match current process. (src_host_tgid=%d; dst_host_tgid=%d; cur_tgid=%d)\n",
304	            src_info->host_tgid, dst_info->host_tgid, cur_tgid);
305	        return DRV_ERROR_NOT_SUPPORT; /* todo: later adapt */
306	    }
307	
308	    return svm_memcpy_local_client(dst_info->devid, dst_info->va, dst_info->size, src_info->va, src_info->size);
309	}
