337	static int svm_async_copy_para_check(u64 dst, u64 dst_max, u64 src, u64 size, u64 *handle)
338	{
339	    int ret;
340	
341	    if (src == 0) {
342	        svm_err("src is 0.\n");
343	        return DRV_ERROR_INVALID_VALUE;
344	    }
345	
346	    if (dst == 0) {
347	        svm_err("dst is 0.\n");
348	        return DRV_ERROR_INVALID_VALUE;
349	    }
350	
351	    if (dst_max == 0) {
352	        svm_err("dst_max is 0.\n");
353	        return DRV_ERROR_INVALID_VALUE;
354	    }
355	
356	    if (size == 0) {
357	        svm_err("cnt is 0.\n");
358	        return DRV_ERROR_INVALID_VALUE;
359	    }
360	
361	    if (dst_max < size) {
362	        svm_err("Dst_max less than size. (dst_max=%llu; size=%llu)\n", dst_max, size);
363	        return DRV_ERROR_INVALID_VALUE;
364	    }
365	
366	    if (handle == NULL) {
367	        svm_err("handle is null.\n");
368	        return DRV_ERROR_INVALID_VALUE;
369	    }
370	
371	    ret = svm_copy_check_addr_prop_cap(dst, size, SVM_FLAG_CAP_ASYNC_COPY_SUBMIT);
372	    if (ret != DRV_ERROR_NONE) {
373	        return ret;
374	    }
375	
376	    return svm_copy_check_addr_prop_cap(src, size, SVM_FLAG_CAP_ASYNC_COPY_SUBMIT);
377	}
