379	DVresult halMemCpyAsync(DVdeviceptr dst, size_t dest_max, DVdeviceptr src, size_t byte_count, uint64_t *copy_fd)
380	{
381	#ifdef CFG_FEATURE_ASYNC_COPY
382	    struct svm_copy_va_info src_info, dst_info;
383	    struct svm_copy_va_info real_src, real_dst;
384	    bool resolved = false;
385	    enum svm_cpy_dir dir;
386	    int ret;
387	
388	    ret = svm_async_copy_para_check(dst, dest_max, src, byte_count, (u64 *)copy_fd);
389	    if (ret != 0) {
390	        return ret;
391	    }
392	
393	    ret = svm_set_copy_va_info((u64)src, (u64)byte_count, &src_info);
394	    if (ret != DRV_ERROR_NONE) {
395	        return ret;
396	    }
397	
398	    ret = svm_set_copy_va_info((u64)dst, (u64)byte_count, &dst_info);
399	    if (ret != DRV_ERROR_NONE) {
400	        return ret;
401	    }
402	
403	    ret = svm_copy_try_resolve_shared_info(&src_info, &dst_info, &real_src, &real_dst, &resolved);
404	    if (ret != DRV_ERROR_NONE) {
405	        return ret;
406	    }
407	
408	    if (resolved) {
409	        svm_info("Async memcpy does not support shared addr. (src=0x%llx; dst=0x%llx; size=%llu)\n", src_info.va,
410	                 dst_info.va, src_info.size);
411	        return DRV_ERROR_NOT_SUPPORT;
412	    }
413	
414	    dir = copy_dir_get_by_devid(src_info.devid, dst_info.devid);
415	    if (dir == SVM_H2H_CPY) {
416	        svm_err("Invalid input, no support H2H async memcpy.\n");
417	        return DRV_ERROR_PARA_ERROR;
418	    }
419	
420	    return svm_async_copy_submit(&src_info, &dst_info, (u64 *)copy_fd);
421	#else
422	    SVM_UNUSED(dst);
423	    SVM_UNUSED(dest_max);
424	    SVM_UNUSED(src);
425	    SVM_UNUSED(byte_count);
426	    SVM_UNUSED(copy_fd);
427	
428	    return DRV_ERROR_NOT_SUPPORT;
429	#endif
430	}
