448	static int _svm_mem_sync_copy(enum svm_cpy_dir dir, struct svm_copy_va_info *src_info,
449	                              struct svm_copy_va_info *dst_info)
450	{
451	    struct svm_dst_va register_va;
452	    u64 host_va = (dir == SVM_H2D_CPY) ? src_info->va : dst_info->va;
453	    u64 size = src_info->size;
454	    u32 user_devid = (dir == SVM_H2D_CPY) ? dst_info->devid : src_info->devid;
455	    u32 flag = 0;
456	    bool is_register = false;
457	    int ret;
458	
459	    svm_dst_va_pack(svm_get_host_devid(), 0, host_va, size, &register_va);
460	
461	    /* TODO: later remove register_to_master, adapt UB behavior same as PCIe */
462	    if ((svm_va_is_in_range(host_va, size) == false) &&
463	        (svm_get_device_connect_type(user_devid) != HOST_DEVICE_CONNECT_TYPE_PCIE)) {
464	        flag |= (dir == SVM_H2D_CPY) ? 0 : REGISTER_TO_MASTER_FLAG_ACCESS_WRITE;
465	        flag |= REGISTER_TO_MASTER_FLAG_PIN;
466	
467	        ret = svm_register_to_master(user_devid, &register_va, flag);
468	        if ((ret != DRV_ERROR_NONE) && (ret != DRV_ERROR_NOT_SUPPORT) && (ret != DRV_ERROR_BUSY)) {
469	            svm_err("Register local mem to master failed. (ret=%d; host_va=0x%llx; size=%llu)\n", ret, host_va, size);
470	            return ret;
471	        }
472	
473	        if (ret == DRV_ERROR_NONE) {
474	            is_register = true;
475	        }
476	    }
477	
478	    ret = svm_sync_copy(src_info, dst_info);
479	    if (is_register) {
480	        (void)svm_unregister_to_master(user_devid, &register_va, flag);
481	    }
482	
483	    return ret;
484	}
