594	static int svm_memcpy_sync(struct svm_copy_va_info *src_info, struct svm_copy_va_info *dst_info)
595	{
596	    struct svm_copy_va_info real_src, real_dst;
597	    enum svm_cpy_dir dir;
598	    bool resolved = false;
599	    u32 exec_devid;
600	    int ret;
601	
602	    dir = copy_dir_get_by_devid(src_info->devid, dst_info->devid);
603	    if ((dir == SVM_H2H_CPY) || ((dir == SVM_D2D_CPY) && (src_info->devid == dst_info->devid))) {
604	        return svm_mem_sync_copy(src_info, dst_info);
605	    }
606	
607	    exec_devid = (dir == SVM_H2D_CPY) ? dst_info->devid : src_info->devid;
608	    if (svm_copy_need_try_resolve_shared_info(exec_devid)) {
609	        ret = svm_copy_try_resolve_shared_info(src_info, dst_info, &real_src, &real_dst, &resolved);
610	        if (ret != DRV_ERROR_NONE) {
611	            return ret;
612	        }
613	
614	        if (resolved) {
615	            dir = copy_dir_get_by_devid(real_src.devid, real_dst.devid);
616	            if ((dir == SVM_H2H_CPY) || ((dir == SVM_D2D_CPY) && (real_src.devid == real_dst.devid))) {
617	                return svm_mem_sync_copy_local_resolved(&real_src, &real_dst);
618	            }
619	            *src_info = real_src;
620	            *dst_info = real_dst;
621	        }
622	    }
623	
624	    return svm_mem_sync_copy(src_info, dst_info);
625	}
