628	DVresult drvMemcpyInner(DVdeviceptr dst, size_t dest_max, DVdeviceptr src, size_t byte_count)
629	{
630	    struct svm_copy_va_info src_info, dst_info;
631	    int ret;
632	
633	    if ((dst == 0) || (src == 0) || (dest_max == 0) || (dest_max < byte_count)) {
634	        svm_err("Invalid argument. (dst=0x%llx; src=0x%llx; byte_count=%lu; dest_max=%lu)\n", dst, src, byte_count,
635	                dest_max);
