637	    }
638	
639	    svm_debug("Memcpy. (dst=0x%llx; src=0x%llx; count=%llu)\n", dst, src, (u64)byte_count);
640	
641	    /* Similar to memcpy_s, (byte_count == 0) need to return 0 */
642	    if (byte_count == 0) {
643	        return DRV_ERROR_NONE;
644	    }
645	
646	    ret = svm_copy_check_addr_prop_cap(dst, byte_count, SVM_FLAG_CAP_SYNC_COPY);
647	    if (ret != DRV_ERROR_NONE) {
648	        return ret;
649	    }
650	
651	    ret = svm_copy_check_addr_prop_cap(src, byte_count, SVM_FLAG_CAP_SYNC_COPY);
652	    if (ret != DRV_ERROR_NONE) {
653	        return ret;
654	    }
655	
656	    ret = svm_set_copy_va_info((u64)src, (u64)byte_count, &src_info);
657	    if (ret != DRV_ERROR_NONE) {
658	        return ret;
659	    }
660	
661	    ret = svm_set_copy_va_info((u64)dst, (u64)byte_count, &dst_info);
662	    if (ret != DRV_ERROR_NONE) {
663	        return ret;
664	    }
665	
