674	    if (ret != DRV_ERROR_NONE) {
675	        /*
676	         * Both src and dst addresses are diagnosed on failure.
677	         * drvMemcpyInner checks dst first (via svm_copy_check_addr_prop_cap),
678	         * then src. The inner function returns a generic error code, so the
679	         * exact failed side is not distinguishable here. Tags "drvMemcpySrcAddr"
680	         * and "drvMemcpyDstAddr" are used to identify each dump.
681	         */
682	        svm_diag_dump_va_prop((u64)src, (u64)byte_count, "drvMemcpySrcAddr");
683	        svm_diag_dump_va_prop((u64)dst, (u64)dest_max, "drvMemcpyDstAddr");
684	    }
685	
