689	static int svm_mem_cpy_para_check(u64 dst, u64 dst_size, u64 src, u64 count, struct memcpy_info *info)
690	{
691	    int ret;
692	
693	    if (dst == 0) {
694	        svm_err("Dst is null.\n");
695	        return DRV_ERROR_INVALID_VALUE;
696	    }
697	
698	    if (src == 0) {
699	        svm_err("Src is null.\n");
700	        return DRV_ERROR_INVALID_VALUE;
701	    }
702	
703	    if (dst_size == 0) {
704	        svm_err("Dst size is zero.\n");
705	        return DRV_ERROR_INVALID_VALUE;
706	    }
707	
708	    if (dst_size < count) {
709	        svm_err("Dst size larger than cpy size. (dst_size=%lu; count=%lu)\n", dst_size, count);
710	        return DRV_ERROR_INVALID_VALUE;
711	    }
712	
713	    /* for halMemcpy */
714	    if (info != NULL) {
715	        if (info->dir != DRV_MEMCPY_DEVICE_TO_HOST) {
716	            svm_info("Invalid dir type. (dir_type=%u)\n", info->dir);
717	            return DRV_ERROR_NOT_SUPPORT;
718	        }
719	
720	        if (info->devid >= SVM_MAX_AGENT_NUM) {
721	            svm_err("Invalid devid. (devid=%u)\n", info->devid);
722	            return DRV_ERROR_INVALID_VALUE;
723	        }
724	
725	        if (!svm_va_is_in_range(src, count) && !va_is_in_sp_range(src, count)) {
726	            return DRV_ERROR_NOT_SUPPORT;
727	        }
728	    }
729	
730	    ret = svm_copy_check_addr_prop_cap(dst, count, SVM_FLAG_CAP_SYNC_COPY_EX);
731	    if (ret != DRV_ERROR_NONE) {
732	        return ret;
733	    }
734	
735	    return svm_copy_check_addr_prop_cap(src, count, SVM_FLAG_CAP_SYNC_COPY_EX);
736	}
737	
738	static drvError_t halMemcpyInner(void *dst, size_t dst_size, void *src, size_t count, struct memcpy_info *info)
739	{
740	    struct svm_copy_va_info src_info, dst_info;
741	    enum svm_cpy_dir dir;
742	    drvError_t ret;
743	
744	    svm_debug("Memcpy. (dst=0x%llx; src=0x%llx; count=%llu)\n", (u64)(uintptr_t)dst, (u64)(uintptr_t)src, (u64)count);
745	
746	    /* Similar to memcpy_s, (count == 0) need to return 0 */
747	    if (count == 0) {
748	        return DRV_ERROR_NONE;
749	    }
750	
751	    ret = svm_mem_cpy_para_check((u64)dst, (u64)dst_size, (u64)src, (u64)count, info);
752	    if (ret != DRV_ERROR_NONE) {
753	        return ret;
754	    }
755	
756	    if (va_is_in_sp_range((u64)src, (u64)count)) {
757	        svm_copy_va_info_pack((u64)src, (u64)count, info->devid, &src_info);
758	    } else {
759	        ret = svm_set_copy_va_info((u64)src, (u64)count, &src_info);
760	        if (ret != DRV_ERROR_NONE) {
761	            return ret;
762	        }
763	    }
764	
765	    ret = svm_set_copy_va_info((u64)dst, (u64)count, &dst_info);
766	    if (ret != DRV_ERROR_NONE) {
767	        return ret;
768	    }
769	
770	    if (info == NULL) {
771	        return svm_mem_sync_copy(&src_info, &dst_info);
772	    } else {
773	        /* D2H copy sp addr. */
774	        dir = copy_dir_get_by_devid(src_info.devid, dst_info.devid);
775	        if (dir != (enum svm_cpy_dir)info->dir) {
776	            svm_err("Invalid addr dir. (dir=%d; info.dir=%d)\n", dir, info->dir);
777	            return DRV_ERROR_INVALID_VALUE;
778	        }
779	
780	        return svm_mem_sync_copy_d2h(&src_info, &dst_info);
781	    }
782	}
