788	    ret = halMemcpyInner(dst, dst_size, src, count, info);
789	    if (ret != DRV_ERROR_NONE) {
790	        /*
791	         * Diagnose both src and dst addresses for failure analysis.
792	         * The inner function (halMemcpyInner -> svm_mem_cpy_para_check)
793	         * validates dst first (via svm_copy_check_addr_prop_cap), then
794	         * src. Multiple paths can fail (param check, addr prop, mem alloc,
795	         * sync copy), making it impossible to pinpoint the exact failed
796	         * side without changing the inner interface. Both addresses are
797	         * dumped here, with "SrcAddr"/"DstAddr" tags to distinguish them.
798	         */
799	        svm_diag_dump_va_prop((u64)src, (u64)count, "halMemcpySrcAddr");
800	        svm_diag_dump_va_prop((u64)dst, (u64)dst_size, "halMemcpyDstAddr");
801	    }
802	
803	    return ret;
804	}
