843	static int svm_dma_desc_dir_check(u32 exec_devid, u32 src_devid, u32 dst_devid)
844	{
845	    enum svm_cpy_dir dir = copy_dir_get_by_devid(src_devid, dst_devid);
846	    int ret = DRV_ERROR_PARA_ERROR;
847	
848	    if (dir == SVM_H2H_CPY) {
849	        svm_err("Invalid input, no support H2H convert.\n");
850	        return DRV_ERROR_PARA_ERROR;
851	    }
852	
853	    if ((dir == SVM_D2D_CPY) && (src_devid == dst_devid)) {
854	        svm_err("Invalid input, Src and dst are same device. (devid=%d)\n", src_devid);
855	        return DRV_ERROR_PARA_ERROR;
856	    }
857	
858	    if (dir == SVM_H2D_CPY) {
859	        ret = (exec_devid != dst_devid) ? DRV_ERROR_INVALID_VALUE : 0;
860	    } else if (dir == SVM_D2H_CPY) {
861	        ret = (exec_devid != src_devid) ? DRV_ERROR_INVALID_VALUE : 0;
862	    } else if (dir == SVM_D2D_CPY) {
863	        ret = ((exec_devid != src_devid) && (exec_devid != dst_devid)) ? DRV_ERROR_INVALID_VALUE : 0;
864	    }
865	    if (ret != DRV_ERROR_NONE) {
866	        svm_err("Exec_devid does not match the direction. (exec_devid=%u; src_devid=%u; dst_devid=%u; dir=%d)\n",
867	                exec_devid, src_devid, dst_devid, dir);
868	        return ret;
869	    }
870	
871	    return DRV_ERROR_NONE;
872	}
