890	
891	    ret = svm_set_copy_va_info((u64)p_dst, (u64)len, &dst_info);
892	    if (ret != DRV_ERROR_NONE) {
893	        return ret;
894	    }
895	
896	    if (svm_copy_need_try_resolve_shared_info(dma_addr->offsetAddr.devid)) {
897	        ret = svm_copy_try_resolve_shared_info(&src_info, &dst_info, &real_src, &real_dst, &resolved);
898	        if (ret != DRV_ERROR_NONE) {
899	            return ret;
900	        }
901	
902	        if (resolved) {
903	            src_info = real_src;
904	            dst_info = real_dst;
905	        }
906	    }
907	
908	    ret = svm_dma_desc_dir_check(dma_addr->offsetAddr.devid, src_info.devid, dst_info.devid);
909	    if (ret != DRV_ERROR_NONE) {
910	        return ret;
911	    }
