1030	static drvError_t svm_2d_sync_copy(struct drvMem2D *sync_2d)
1031	{
1032	    struct svm_copy_va_2d_info src_info, dst_info;
1033	    enum svm_cpy_dir dir;
1034	    int ret;
1035	
1036	    svm_debug(
1037	        "2D sync copy. (src=0x%llx; dst=0x%llx; spitch=%llu; dpitch=%llu; width=%llu; height=%llu; direction=%u)\n",
1038	        sync_2d->src, sync_2d->dst, sync_2d->spitch, sync_2d->dpitch, sync_2d->width, sync_2d->height,
1039	        sync_2d->direction);
1040	    ret = svm_copy_check_addr_prop_cap((u64)(uintptr_t)sync_2d->src,
1041	                                       sync_2d->spitch * (sync_2d->height - 1) + sync_2d->width,
1042	                                       SVM_FLAG_CAP_SYNC_COPY_2D);
1043	    if (ret != DRV_ERROR_NONE) {
1044	        return ret;
1045	    }
1046	
1047	    ret = svm_copy_check_addr_prop_cap((u64)(uintptr_t)sync_2d->dst,
1048	                                       sync_2d->dpitch * (sync_2d->height - 1) + sync_2d->width,
1049	                                       SVM_FLAG_CAP_SYNC_COPY_2D);
1050	    if (ret != DRV_ERROR_NONE) {
1051	        return ret;
1052	    }
1053	
1054	    ret = svm_set_copy_va_2d_info((u64)(uintptr_t)sync_2d->src, sync_2d->spitch, sync_2d->width, sync_2d->height,
1055	                                  &src_info);
1056	    if (ret != DRV_ERROR_NONE) {
1057	        return ret;
1058	    }
1059	
1060	    ret = svm_set_copy_va_2d_info((u64)(uintptr_t)sync_2d->dst, sync_2d->dpitch, sync_2d->width, sync_2d->height,
1061	                                  &dst_info);
1062	    if (ret != DRV_ERROR_NONE) {
1063	        return ret;
1064	    }
1065	
1066	    dir = copy_dir_get_by_devid(src_info.devid, dst_info.devid);
1067	    if ((dir == SVM_H2H_CPY) || (dir == SVM_D2D_CPY)) {
1068	        svm_info("Not support h2h, d2d copy.\n");
1069	        return DRV_ERROR_NOT_SUPPORT;
1070	    }
1071	
1072	    if (dir != sync_2d->direction) {
1073	        svm_err("Act cpy dir is diff from para dir. (act_dir=%u; para_dir=%u; src=0x%llx; dst=0x%llx)\n", dir,
1074	                sync_2d->direction, sync_2d->src, sync_2d->dst);
1075	        return DRV_ERROR_PARA_ERROR;
1076	    }
1077	
