1096	    if (info_2d->fixed_size >= (info_2d->width * info_2d->height)) {
1097	        svm_err("Fixed_size should smaller than width*height. (fixed_size=%llu; width=%llu; height=%llu)\n",
1098	                info_2d->fixed_size, info_2d->width, info_2d->height);
