1145	    if (((dir == SVM_H2D_CPY) && (convert_2d->dmaAddr->offsetAddr.devid != dst_info.devid)) ||
1146	        ((dir == SVM_D2H_CPY) && (convert_2d->dmaAddr->offsetAddr.devid != src_info.devid))) {
