140	int svm_ipc_query_src_info(u64 opened_va, u64 size, struct svm_global_va *src_info)
141	{
142	    struct svm_prop prop;
143	    u64 offset;
144	    int ret;
145	
146	    ret = svm_get_prop(opened_va, &prop);
147	    if (ret != 0) {
148	        return DRV_ERROR_NOT_EXIST;
149	    }
150	
151	    if (!svm_flag_cap_is_support_ipc_close(prop.flag)) {
152	        return DRV_ERROR_NOT_EXIST;
153	    }
154	
155	    ret = _svm_ipc_query_src_info(prop.start, src_info);
156	    if (ret != 0) {
157	        return DRV_ERROR_NOT_EXIST;
158	    }
159	
160	    offset = opened_va - prop.start;
161	    if ((offset >= src_info->size) || (size > (src_info->size - offset))) {
162	        svm_err("Out of range. (va=0x%llx; size=0x%llx; start=0x%llx; opened_size=0x%llx)\n", opened_va, size,
163	                prop.start, src_info->size);
164	        return DRV_ERROR_INVALID_VALUE;
165	    }
166	
167	    src_info->va += offset;
168	    src_info->size = size;
169	    return DRV_ERROR_NONE;
170	}
