172	static void svm_ipc_info_byte_to_replace_bitmap(u32 info_byte, u32 *bitmap_byte, u32 *bitmap_bit)
173	{
174	    *bitmap_byte = info_byte / IPC_BTYE_NUM_PER_REPLACE_BITMAP_BYTE;
175	    *bitmap_bit = info_byte % IPC_BTYE_NUM_PER_REPLACE_BITMAP_BYTE;
176	}
177	
178	static void svm_ipc_replace_bitmap_to_info_byte(u32 bitmap_byte, u32 bitmap_bit, u32 *info_byte)
179	{
180	    *info_byte = bitmap_byte * IPC_BTYE_NUM_PER_REPLACE_BITMAP_BYTE + bitmap_bit;
181	}
