183	static int svm_ipc_parse_name(const char *name, u8 *version, u64 *key, int *cs_valid, struct svm_global_va *src_va,
184	                              int *owner_pid)
185	{
186	    struct svm_ipc_info ipc_info;
187	    const u8 *replace_bitmap = (const u8 *)(const void *)(name + IPC_INFO_LEN);
188	    u8 *ipc_info_byte = (u8 *)(void *)&ipc_info;
189	    u32 i, j;
190	
191	    if (strnlen(name, SVM_MAX_IPC_NAME_SIZE) < IPC_FORMAT_TOTAL_LEN) {
192	        return DRV_ERROR_INVALID_VALUE;
193	    }
194	
195	    ipc_info = *(const struct svm_ipc_info *)(const void *)name;
196	    for (i = 0; i < IPC_REPLACE_BITMAP_LEN; i++) {
197	        for (j = 0; j < IPC_BTYE_NUM_PER_REPLACE_BITMAP_BYTE; j++) {
198	            if ((replace_bitmap[i] & (0x1 << j)) != 0) {
199	                u32 info_byte;
200	                svm_ipc_replace_bitmap_to_info_byte(i, j, &info_byte);
201	                if (info_byte >= IPC_INFO_LEN) {
202	                    svm_err("Invalid name. (name=%s; info_byte=%u).\n", name, info_byte);
203	                    return DRV_ERROR_INVALID_VALUE;
204	                }
205	                ipc_info_byte[info_byte] = 0;
206	            }
207	        }
208	    }
209	
210	    *version = ipc_info.ver;
211	    *cs_valid = (int)ipc_info.cs_valid;
212	    *key = ipc_info.key;
213	    *owner_pid = ipc_info.owner_pid;
214	    src_va->server_id = (u32)ipc_info.server_id;
215	    src_va->udevid = (u32)ipc_info.udevid;
216	    src_va->tgid = ipc_info.tgid;
217	    src_va->va = ipc_info.va;
218	    src_va->size = ipc_info.size;
219	
220	    return DRV_ERROR_NONE;
221	}
