232	static int svm_ipc_format_name(char *name, u32 name_len, u64 key)
233	{
234	    struct svm_ipc_info *ipc_info = (struct svm_ipc_info *)(void *)name;
235	    u8 *replace_bitmap = (u8 *)(void *)(ipc_info + 1);
236	    u8 *ipc_info_byte = (u8 *)(void *)ipc_info;
237	    u8 version = SVM_IPC_NAME_VERSION_00;
238	    struct svm_global_va src_va = {0};
239	    struct svm_global_va tmp_src_va;
240	    int owner_pid = 0;
241	    int tmp_owner_pid;
242	    int cs_valid = 0;
243	    int ret;
244	    u32 i;
245	
246	    ret = svm_casm_cs_query_src_info(key, &tmp_src_va, &tmp_owner_pid);
247	    if (ret == 0) {
248	        if (tmp_src_va.server_id != SVM_INVALID_SERVER_ID) {
249	            cs_valid = 1;
250	            src_va = tmp_src_va;
251	            owner_pid = tmp_owner_pid;
252	        }
253	    }
254	
255	    if (name_len <= (IPC_FORMAT_TOTAL_LEN + 1)) { /* '\0' + 1 */
256	        svm_err("Not enough spcace. (name_len=%u; need=%u)\n", name_len, IPC_FORMAT_TOTAL_LEN);
257	        return DRV_ERROR_INVALID_VALUE;
258	    }
259	
260	    ipc_info->ver = version;
261	    ipc_info->cs_valid = (u8)cs_valid;
262	    ipc_info->rsv = 0;
263	    ipc_info->key = key;
264	    ipc_info->owner_pid = owner_pid;
265	    ipc_info->server_id = (u16)src_va.server_id;
266	    ipc_info->udevid = (u16)src_va.udevid;
267	    ipc_info->tgid = src_va.tgid;
268	    ipc_info->va = src_va.va;
269	    ipc_info->size = src_va.size;
270	
271	    for (i = 0; i < IPC_REPLACE_BITMAP_LEN; i++) {
272	        replace_bitmap[i] = 0x1 << IPC_BTYE_NUM_PER_REPLACE_BITMAP_BYTE;
273	    }
274	
275	    name[IPC_FORMAT_TOTAL_LEN] = '\0';
276	
277	    for (i = 0; i < IPC_INFO_LEN; i++) {
278	        if (ipc_info_byte[i] == 0) {
279	            u32 bitmap_byte, bitmap_bit;
280	            svm_ipc_info_byte_to_replace_bitmap(i, &bitmap_byte, &bitmap_bit);
281	            replace_bitmap[bitmap_byte] |= (u8)(0x1 << bitmap_bit);
282	            ipc_info_byte[i] = 1;
283	        }
284	    }
285	
286	    return DRV_ERROR_NONE;
287	}
