289	static int svm_ipc_create_handle(u64 va, u64 size, u64 *key)
290	{
291	    struct svm_dst_va dst_va;
292	    struct svm_prop prop;
293	    u64 aligned_size;
294	    int ret;
295	
296	    ret = svm_get_prop(va, &prop);
297	    if (ret != 0) {
298	        svm_err("Get prop failed. (va=0x%llx)\n", va);
299	        return ret;
300	    }
301	
302	    if (!svm_flag_cap_is_support_ipc_create(prop.flag)) {
303	        svm_err("Addr cap is not support ipc create. (va=0x%llx)\n", va);
304	        return DRV_ERROR_PARA_ERROR;
305	    }
306	
307	    ret = svm_share_get_src_aligned_size(prop.devid, prop.flag, va, size, &aligned_size);
308	    if (ret != 0) {
309	        svm_err("Get aligned size failed. (devid=%u; va=0x%llx; size=0x%llx)\n", prop.devid, va, size);
310	        return DRV_ERROR_PARA_ERROR;
311	    }
312	
313	    if ((va + size) > (prop.start + prop.size)) {
314	        svm_err("va or size is invalid. (va=0x%llx; align_size=0x%llx; prop start=0x%llx; size=0x%llx)\n", va,
315	                aligned_size, prop.start, prop.size);
316	        return DRV_ERROR_PARA_ERROR;
317	    }
318	
319	    svm_dst_va_pack(prop.devid, DEVDRV_PROCESS_CP1, va, aligned_size, &dst_va);
320	    ret = svm_casm_create_key(&dst_va, key);
321	    if (ret != 0) {
322	        /* The log cannot be modified, because in the failure mode library. */
323	        svm_err("Create key failed. (va=0x%llx)\n", va);
324	        return ret;
325	    }
326	
327	    return 0;
328	}
