374	{
375	    u32 map_route = (u32)ipc_open_flag;
376	    u32 casm_flag = 0;
377	
378	    casm_flag |= (map_route == MEM_MAP_UB_ONE_PORT_PATH) ? SVM_CASM_FLAG_MAP_UB_ONE_PORT_PATH : 0;
