384	static int svm_ipc_open_handle(u32 devid, u64 key, u64 *opened_va, uint64_t flag)
385	{
386	    struct svm_global_va src_va;
387	    u64 access_va = 0;
388	    u64 update_va, align;
389	    int ret;
390	
391	    ret = svm_casm_get_src_va_ex(devid, key, &src_va, &update_va, &access_va);
392	    if (ret != 0) {
393	        svm_err("Get src va failed. (devid=%u; key=0x%llx)\n", devid, key);
394	        return ret;
395	    }
396	
397	    if (access_va != 0) {
398	        *opened_va = access_va;
399	        return 0;
400	    }
401	
402	    ret = svm_share_get_dst_align(src_va.va, src_va.size, devid, &align);
403	    if (ret != DRV_ERROR_NONE) {
404	        svm_err("Get dst align failed. (ret=%d; src_va=0x%llx; size=%llu; devid=%u)\n", ret, src_va.va, src_va.size,
405	                devid);
406	        return ret;
407	    }
408	
409	    ret = svm_ipc_malloc_opened_va(devid, svm_get_non_dev_align_size(src_va.size), align, opened_va);
410	    if (ret != 0) {
411	        svm_err("Malloc opened va failed. (devid=%u; key=0x%llx; size=0x%llx; align=0x%llx)\n", devid, key, src_va.size,
412	                align);
413	        return ret;
414	    }
415	
416	    ret = svm_casm_mem_map(devid, *opened_va, src_va.size, key, svm_ipc_open_flag_to_casm_flag(flag));
417	    if (ret != 0) {
418	        (void)svm_ipc_free_opened_va(*opened_va);
419	        svm_err("Mem map failed. (devid=%u; key=0x%llx; size=0x%llx; opened_va=0x%llx)\n", devid, key, src_va.size,
420	                *opened_va);
421	        return ret;
422	    }
423	
424	    svm_mod_va_devid(*opened_va, devid);
425	    ret = svm_ipc_set_opened_src_info(*opened_va, &src_va);
426	    if (ret != 0) {
427	        (void)svm_casm_mem_unmap(devid, *opened_va, src_va.size);
428	        (void)svm_ipc_free_opened_va(*opened_va);
429	        return ret;
430	    }
431	
432	    return 0;
433	}
