435	static int svm_ipc_close_handle(u64 opened_va)
436	{
437	    struct svm_global_va src_va;
438	    struct svm_prop prop;
439	    int ret;
440	
441	    if (svm_is_in_linear_mem_va_range(opened_va, 1ULL)) {
442	        return 0;
443	    }
444	
445	    ret = svm_get_prop(opened_va, &prop);
446	    if (ret != 0) {
447	        svm_err("Get prop failed. (va=0x%llx)\n", opened_va);
448	        return ret;
449	    }
450	
451	    if (!svm_flag_cap_is_support_ipc_close(prop.flag)) {
452	        svm_err("Addr cap is not support ipc close. (opened_va=0x%llx)\n", opened_va);
453	        return DRV_ERROR_PARA_ERROR;
454	    }
455	
456	    ret = _svm_ipc_query_src_info(prop.start, &src_va);
457	    if (ret != 0) {
458	        svm_err("Src_info is not exist. (va=0x%llx)\n", prop.start);
459	        return DRV_ERROR_NOT_EXIST;
460	    }
461	
462	    ret = svm_casm_mem_unmap(prop.devid, opened_va, src_va.size);
463	    if (ret != 0) {
464	        svm_err("Mem unmap failed. (devid=%u; size=0x%llx; opened_va=0x%llx)\n", prop.devid, src_va.size, opened_va);
465	        return ret;
466	    }
467	
468	    ret = svm_ipc_free_opened_va(opened_va);
469	    if (ret != 0) {
470	        svm_warn("Free failed. (devid=%u; opened_va=0x%llx)\n", prop.devid, opened_va);
471	    }
472	
473	    return 0;
474	}
