    if ((g_copy_ops[devid] == NULL) || (g_copy_ops[devid]->dma_desc_convert_2d == NULL)) {
        return DRV_ERROR_NOT_SUPPORT;
    }

    return g_copy_ops[devid]->dma_desc_convert_2d(devid, src_info, dst_info, fixed_size, dma_desc);
