30	static int svm_memcpy_local_event(u32 devid, u64 dst, u64 dst_max, u64 src, u64 count)
31	{
32	    struct svm_umc_msg_head head;
33	    struct svm_memcpy_local_msg memcpy_local_msg = {.src = src, .dst = dst, .size = count};
34	    struct svm_umc_msg msg = {.msg_in = (char *)(uintptr_t)&memcpy_local_msg,
35	                              .msg_in_len = sizeof(struct svm_memcpy_local_msg),
36	                              .msg_out = NULL,
37	                              .msg_out_len = 0};
38	    struct svm_apbi apbi;
39	    int ret;
40	    SVM_UNUSED(dst_max);
41	
42	    ret = svm_apbi_query(devid, DEVDRV_PROCESS_CP1, &apbi);
43	    if (ret != DRV_ERROR_NONE) {
44	        return ret;
45	    }
46	
47	    svm_umc_msg_head_pack(devid, apbi.tgid, apbi.grp_id, SVM_MEMCPY_LOCAL_EVENT, &head);
48	    ret = svm_umc_h2d_send(&head, &msg);
49	    if (ret == DRV_ERROR_NO_PROCESS) {
50	        (void)svm_apbi_clear(devid, DEVDRV_PROCESS_CP1);
51	    }
52	
53	    return ret;
54	}
