56	int svm_memcpy_local_client(u32 devid, u64 dst, u64 dst_max, u64 src, u64 count)
57	{
58	    if (devid != svm_get_host_devid()) {
59	        return svm_memcpy_local_event(devid, dst, dst_max, src, count);
60	    } else {
61	        return svm_memcpy_local(dst, dst_max, src, count);
62	    }
