25	static int _svm_memcpy_local(u64 dst, u64 dst_max, u64 src, u64 count)
26	{
27	    int ret;
28	
29	    ret = halSdmaCopy(dst, dst_max, src, count);
30	    if (ret != 0) {
31	        ret = svm_memcpy_s((void *)(uintptr_t)dst, dst_max, (void *)(uintptr_t)src, count);
32	    }
33	
34	    return ret;
35	}
36	
37	static bool is_memcpy_overlap(u64 dst, u64 src, u64 count)
38	{
39	    u64 src_end = src + count;
40	    u64 dst_end = dst + count;
41	    return (((src >= dst) && (src < dst_end)) || ((dst >= src) && (dst < src_end)));
42	}
43	
44	int svm_memcpy_local(u64 dst, u64 dst_max, u64 src, u64 count)
45	{
46	    size_t split_size = svm_min(SECUREC_MEM_MAX_LEN, SDMA_MAX_COPY_SIZE);
47	    size_t rest_count, per_count;
48	    u64 tmp_dst = dst;
49	    u64 tmp_src = src;
50	    int ret;
51	
52	    if (dst_max < count) {
53	        svm_err("Count bigger than dstMax. (dst=0x%llx; src=0x%llx; count=%llu; dstMax=%llu)\n", tmp_dst, tmp_src,
54	                count, dst_max);
55	        return DRV_ERROR_INVALID_VALUE;
56	    }
57	
58	    if (is_memcpy_overlap(tmp_dst, tmp_src, count)) {
59	        svm_err("Memcpy overlap. (dst=0x%llx; src=0x%llx; count=%llu; dstMax=%llu)\n", tmp_dst, tmp_src, count,
60	                dst_max);
61	        return DRV_ERROR_INVALID_VALUE;
62	    }
63	
64	    if (count <= split_size) {
65	        ret = _svm_memcpy_local(tmp_dst, count, tmp_src, count);
66	        if (ret != 0) {
67	            svm_err("Memcpy error. (dst=0x%llx; dstMax=%llu; src=0x%llx; count=%llu; ret=%d)\n", tmp_dst, dst_max,
68	                    tmp_src, count, ret);
69	            return DRV_ERROR_INVALID_VALUE;
70	        }
71	    } else {
72	        for (rest_count = count; rest_count > 0;) {
73	            per_count = rest_count > split_size ? split_size : rest_count;
74	            ret = _svm_memcpy_local(tmp_dst, per_count, tmp_src, per_count);
75	            if (ret != 0) {
76	                svm_err("Memcpy error. (dst=0x%llx; src=0x%llx; per_count=%lu; ret=%d)\n", tmp_dst, tmp_src, per_count,
77	                        ret);
78	                return DRV_ERROR_INVALID_VALUE;
79	            }
80	            tmp_dst = tmp_dst + per_count;
81	            tmp_src = tmp_src + per_count;
82	            rest_count = rest_count - per_count;
83	        }
84	    }
85	
86	    return DRV_ERROR_NONE;
